            try c.setOwner(newOwner) returns (bool success) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        address ownerAfter = c.owner();
        if (reverted) {
            assert(ownerAfter == ownerBefore);
        } else {
            assert(ownerAfter == newOwner);
        }
    }
}

